import { useRecoilState, useRecoilValue } from "recoil";
import { Category, categoryState, toDoListState, toDoSelector } from "../atoms";
import CreateToDo from "./CreateToDo";
import ToDo from "./ToDo";
import styled from "styled-components";

const Container = styled.div`
	padding: 20px;
	max-width: 480px;
	margin: 0 auto;
`;

const Header = styled.header`
	height: 20vh;
	display: flex;
  justify-content: center;
  align-items: center;
	h1 {
		font-size: 40px;
		font-weight: bolder;
		color: ${(props) => props.theme.textColors.normal}
	}
`;

const Tabs = styled.div`
	display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin: 25px 0px;
  gap: 16px;
	/* border-bottom: 1px solid ${props => props.theme.bgColors.dimmed}; */
	border-bottom: 1px solid ${props => props.theme.bgColors.reversed};
`;

const Tab = styled.button<{isActive: boolean}>`
  text-align: center;
  /* text-transform: uppercase; */
  font-size: 12px;
  font-weight: 400;
  padding: 6px 20px;
	/* border-radius: 12px;  */
	/* background-color: ${(props) => props.theme.bgColors.dimmed}; */
	background-color: transparent;
  color: ${(props) => props.theme.textColors.normal};
	border-bottom: 1px solid ;
	border-color: ${(props) => 
		props.isActive ? props.theme.textColors.normal : "transparent"
	};
	/* &:active {
		color: ${ ( props ) => props.theme.brandColors.primary };
		border-color: ${ ( props ) => props.theme.brandColors.primary } ;
	}
	&:hover {

	} */
`;


function ToDoList() {
  const toDos = useRecoilValue(toDoListState);
	const [selectedCategory, setSelectedCategory] = useRecoilState(categoryState);

	const [to_do, doing, done] = useRecoilValue(toDoSelector);

  return (
    <Container>
      <Header>
				<h1>To Do List</h1>
			</Header>
			<Tabs>
				<Tab isActive={selectedCategory === Category.all}>all</Tab>
				<Tab isActive={selectedCategory === Category.to_do}>to do</Tab>
				<Tab isActive={selectedCategory === Category.in_progress}>in progress</Tab>
				<Tab isActive={selectedCategory === Category.done}>done</Tab>
			</Tabs>

      {/* <hr /> */}
      <CreateToDo />
			<div style={{display: "flex", gap: 10}}>
				<ul style={{minWidth: 100, backgroundColor: "#000", gap: "10px"}}>
        {to_do.map((toDo) => (
          <ToDo key={toDo.id} {...toDo} />
        ))}
				</ul>
				<ul style={{minWidth: 100, backgroundColor: "#000"}}>
					{doing.map((toDo) => (
						<ToDo key={toDo.id} {...toDo} />
					))}
				</ul>
				<ul style={{minWidth: 100, backgroundColor: "#000"}}>
					{done.map((toDo) => (
						<ToDo key={toDo.id} {...toDo} />
					))}
				</ul>
			</div>
		</Container>
  );
}

export default ToDoList;
